The graph is given as an adjacency matrix. A recursive search assigns a color to one vertex at a time. Before assigning, it checks all already colored neighbors. If no color works, it removes the previous color and tries another choice.

For example, with 3 colors, the first vertex may get color 0. If the next vertex is connected to it, color 0 is skipped and color 1 is tried. The search returns as soon as every vertex has a valid color.

```cpp
#include <bits/stdc++.h>
using namespace std;

class Solution{
    bool canUseColor(int vertex, int color, vector<int>& colors,
                    vector<vector<int>>& edges, int n) {
        for (int other = 0; other < n; other++) {
            if (edges[vertex][other] != 0 && colors[other] == color) {
                return false;
            }
        }
        return true;
    }

    bool assignColor(int vertex, vector<int>& colors,
                     vector<vector<int>>& edges, int m, int n) {
        if (vertex == n) {
            return true;
        }

        for (int color = 0; color < m; color++) {
            if (canUseColor(vertex, color, colors, edges, n)) {
                colors[vertex] = color;

                if (assignColor(vertex + 1, colors, edges, m, n)) {
                    return true;
                }

                colors[vertex] = -1;
            }
        }
        return false;
    }

public:
    bool graphColoring(vector<vector<int> >& edges, int m, int n) {
        if (n == 0) return true;
        if (m <= 0) return false;

        vector<int> colors(n, -1);
        return assignColor(0, colors, edges, m, n);
    }
};
```

In the worst case, the time is `O(m^n * n)`, since each vertex can try `m` colors and checking a color scans its row. The recursion uses `O(n)` extra space, not counting the input matrix.

This keeps the usual backtracking idea, but first sorts vertices by degree. The vertices with more edges are handled earlier. For each vertex, the code checks the colors of its neighbors and then moves forward.

A small dry run: if the ordered vertices are `[1, 0, 2]` and two colors are available, vertex 1 gets color 0. If vertex 0 is connected to 1, it tries color 1. If vertex 2 conflicts with both choices, the code goes back to vertex 0 and tries another color.

The matrix is expected to contain `1` for an edge and `0` otherwise. A graph with no vertices is considered colorable.

```python
class Solution:
    def graphColoring(self, edges, m, n):
        if n == 0:
            return True
        if m <= 0:
            return False

        order = list(range(n))
        order.sort(key=lambda vertex: sum(edges[vertex]), reverse=True)
        colors = [-1] * n

        def is_allowed(vertex, color):
            for neighbor in range(n):
                if edges[vertex][neighbor] != 0 and colors[neighbor] == color:
                    return False
            return True

        def backtrack(position):
            if position == n:
                return True

            vertex = order[position]
            for color in range(m):
                if is_allowed(vertex, color):
                    colors[vertex] = color
                    if backtrack(position + 1):
                        return True
                    colors[vertex] = -1
            return False

        return backtrack(0)
```

The search can take `O(m^n * n)` time in the worst case. Sorting takes `O(n log n)` after the matrix rows are summed. The recursion and color list use `O(n)` extra space, apart from the input.

A fixed vertex order can make the search slow on some graphs. This version chooses the uncolored vertex with the highest degree first. Such a vertex usually has more restrictions, so a wrong choice is found earlier.

The `colors` array stores `-1` for an uncolored vertex. The input matrix is only read, so it is not changed. If `m` is zero and there are vertices, no coloring is possible.

```java
class Solution {
    private boolean canColor(int vertex, int color, int[][] edges,
                             int[] colors, int n) {
        for (int neighbor = 0; neighbor < n; neighbor++) {
            if (edges[vertex][neighbor] != 0 && colors[neighbor] == color) {
                return false;
            }
        }
        return true;
    }

    private int chooseVertex(int[][] edges, int[] colors, int n) {
        int chosen = -1;
        int bestDegree = -1;

        for (int vertex = 0; vertex < n; vertex++) {
            if (colors[vertex] != -1) continue;

            int degree = 0;
            for (int neighbor = 0; neighbor < n; neighbor++) {
                if (edges[vertex][neighbor] != 0) {
                    degree++;
                }
            }

            if (degree > bestDegree) {
                bestDegree = degree;
                chosen = vertex;
            }
        }
        return chosen;
    }

    private boolean search(int[][] edges, int[] colors, int m, int n,
                           int coloredCount) {
        if (coloredCount == n) {
            return true;
        }

        int vertex = chooseVertex(edges, colors, n);
        for (int color = 0; color < m; color++) {
            if (canColor(vertex, color, edges, colors, n)) {
                colors[vertex] = color;
                if (search(edges, colors, m, n, coloredCount + 1)) {
                    return true;
                }
                colors[vertex] = -1;
            }
        }
        return false;
    }

    boolean graphColoring(int[][] edges, int m, int n) {
        if (n == 0) return true;
        if (m <= 0) return false;

        int[] colors = new int[n];
        java.util.Arrays.fill(colors, -1);
        return search(edges, colors, m, n, 0);
    }
}
```

The worst-case time is `O(m^n * n)`. Choosing a high-degree vertex can reduce the practical search, but it does not change that worst case. Extra space is `O(n)` for the color array and recursion calls.

The search below uses a saturation count to choose the next vertex. Saturation means how many different colors are already used by its colored neighbors. A vertex with a larger count has fewer safe choices, so it is tested first.

The input is an adjacency matrix stored in the required `List<List<int>>` form. Only the `colors` array changes during the search. A one-vertex graph succeeds whenever at least one color is available.

```csharp
using System;
using System.Collections.Generic;

public class Solution
{
    private bool CanUse(List<List<int>> edges, int[] colors,
                        int vertex, int color, int n)
    {
        for (int neighbor = 0; neighbor < n; neighbor++)
        {
            if (edges[vertex][neighbor] != 0 && colors[neighbor] == color)
            {
                return false;
            }
        }
        return true;
    }

    private int PickVertex(List<List<int>> edges, int[] colors,
                           int m, int n)
    {
        int selected = -1;
        int bestSaturation = -1;
        int bestDegree = -1;

        for (int vertex = 0; vertex < n; vertex++)
        {
            if (colors[vertex] != -1) continue;

            bool[] used = new bool[m];
            int saturation = 0;
            int degree = 0;

            for (int neighbor = 0; neighbor < n; neighbor++)
            {
                if (edges[vertex][neighbor] == 0) continue;
                degree++;

                int neighborColor = colors[neighbor];
                if (neighborColor >= 0 && neighborColor < m && !used[neighborColor])
                {
                    used[neighborColor] = true;
                    saturation++;
                }
            }

            if (saturation > bestSaturation ||
                (saturation == bestSaturation && degree > bestDegree))
            {
                selected = vertex;
                bestSaturation = saturation;
                bestDegree = degree;
            }
        }

        return selected;
    }

    private bool Search(List<List<int>> edges, int[] colors,
                        int m, int n, int colored)
    {
        if (colored == n) return true;

        int vertex = PickVertex(edges, colors, m, n);
        for (int color = 0; color < m; color++)
        {
            if (CanUse(edges, colors, vertex, color, n))
            {
                colors[vertex] = color;
                if (Search(edges, colors, m, n, colored + 1))
                {
                    return true;
                }
                colors[vertex] = -1;
            }
        }

        return false;
    }

    public bool graphColoring(List<List<int>> edges, int m, int n)
    {
        if (n == 0) return true;
        if (m <= 0) return false;

        int[] colors = new int[n];
        Array.Fill(colors, -1);
        return Search(edges, colors, m, n, 0);
    }
}
