class Solution {
  graphColoring(edges, m, n) {
    const adjacentNodes = this.constructAdjacentNodes(edges, n);
    const colors = new Array(n).fill(-1);
    return this.canBeColored(adjacentNodes, 0, colors, m, n);
  }
  canBeColored(adjacentNodes, level, colors, m, n) {
    if (level === n) {
      return true;
    }
    for (let i = 0; i < m; i++) {
      if (this.isPossibleToColor(adjacentNodes, level, i, colors)) {
        colors[level] = i;
        if (this.canBeColored(adjacentNodes, level + 1, colors, m, n))
          return true;
        colors[level] = -1;
      }
    }
    return false;
  }

  isPossibleToColor(adjacentNodes, level, currColor, colors) {
    const adjacent = adjacentNodes[level];
    for (const value of adjacent) {
      if (colors[value] === currColor) {
        return false;
      }
    }
    return true;
  }

  constructAdjacentNodes(edges, n) {
    const obj = {};
    for (let i = 0; i < n; i++) {
      obj[i] = new Set();
    }
    for (let i = 0; i < edges.length; i++) {
      const [a, b] = edges[i];
      obj[a].add(b);
      obj[b].add(a);
    }
    return obj;
  }
}

