class Solution {
    boolean graphColoring(int[][] edges, int m, int n) {
        LinkedList<Integer>[] adjList = new LinkedList[n];
        int[] colors = new int[n];
        for(int i=0; i<n; i++){
            adjList[i] = new LinkedList<>();
        }
        for(int[] edge : edges){
            adjList[edge[0]].add(edge[1]);
            adjList[edge[1]].add(edge[0]);
        }
        return solveGraphColoring(adjList, m, n, 0, colors);
    }

    boolean solveGraphColoring(LinkedList<Integer>[] adjList, int m, int n, int vertex, int[] colors){
        if(vertex==n) return true;

        for(int i=1; i<=m; i++){
            if(safe(vertex, i, colors, adjList)){
                colors[vertex] = i;
                if(solveGraphColoring(adjList, m, n, vertex+1, colors)) return true;
                colors[vertex] = 0;
            }
        }
        return false;
    }

    boolean safe(int vertex, int color, int[] colors, LinkedList<Integer>[] adjList){
        for(int adj :  adjList[vertex]){
            if(colors[adj]==color){
                return false;
            }
        }
        return true;
    }
}
